import {useId} from "react";
import type {FormEvent} from "react";
export const AREAS=["tickets","dashboard","other"] as const;
export type Area=(typeof AREAS)[number];
export const TAGS=["api","ui","export","auth"] as const;
export type Tag=(typeof TAGS)[number];
export type Feedback={email:string;area:Area;message:string;contactMe:boolean;tags:Tag[];attachment:File|null};
export function readText(data:FormData,name:string):string|null{const value=data.get(name);return typeof value==="string"?value:null;}
export function isArea(value:string):value is Area{return AREAS.some(area=>area===value);}
export function isTag(value:string):value is Tag{return TAGS.some(tag=>tag===value);}
export function readFeedback(data:FormData):Feedback|null{const email=readText(data,"email");const area=readText(data,"area");const message=readText(data,"message");if(email===null||email.trim()===""||area===null||!isArea(area)||message===null||message.trim()==="")return null;const tags:Tag[]=[];for(const value of data.getAll("tags")){if(typeof value!=="string"||!isTag(value))return null;if(!tags.includes(value))tags.push(value);}const rawFile=data.get("attachment");if(rawFile!==null&&!(rawFile instanceof File))return null;return {email:email.trim(),area,message,contactMe:data.get("contactMe")==="on",tags,attachment:rawFile instanceof File&&rawFile.name!==""?rawFile:null};}
export function fileInfo(file:File|null):string{return file?`${file.name} (${Math.round(file.size/1024)} KiB)`:"Brak pliku";}
export function FeedbackForm({onSend,onInvalid}:{onSend:(feedback:Feedback)=>void;onInvalid?:(message:string)=>void}){const id=useId();function handleSubmit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const feedback=readFeedback(data);if(feedback===null){onInvalid?.("Sprawdź wymagane pola i wybrane wartości");return;}onSend(feedback);form.reset();}return <form onSubmit={handleSubmit} className="feedback-form"><label htmlFor={`${id}-email`}>E-mail</label><input id={`${id}-email`} name="email" type="email" required/><label htmlFor={`${id}-area`}>Obszar</label><select id={`${id}-area`} name="area" defaultValue="tickets">{AREAS.map(area=><option key={area} value={area}>{area}</option>)}</select><label htmlFor={`${id}-message`}>Opis</label><textarea id={`${id}-message`} name="message" required rows={4}/><label><input type="checkbox" name="contactMe" defaultChecked/>Skontaktujcie się ze mną</label><fieldset><legend>Tagi</legend>{TAGS.map(tag=><label key={tag}><input type="checkbox" name="tags" value={tag}/>{tag}</label>)}</fieldset><label htmlFor={`${id}-file`}>Załącznik</label><input id={`${id}-file`} name="attachment" type="file" accept="image/*,.pdf"/><button type="submit">Wyślij</button></form>;}

