import {useState} from "react";
import {FeedbackForm} from "./FeedbackForm";
import type {Feedback} from "./FeedbackForm";
import "./App.css";
export default function App(){const [feedback,setFeedback]=useState<Feedback|null>(null);const [message,setMessage]=useState("");return <main><h1>Zgłoś problem</h1><FeedbackForm onSend={value=>{setFeedback(value);setMessage("Dziękujemy!");}} onInvalid={setMessage}/><p role="status">{message}</p>{feedback&&<section><h2>Przekazane dane</h2><p>{feedback.email} — {feedback.area}</p><p>{feedback.message}</p><p>Kontakt: {feedback.contactMe?"tak":"nie"}</p><p>Tagi: {feedback.tags.join(", ")||"brak"}</p><p>Plik: {feedback.attachment?.name??"brak"}</p></section>}</main>;}

